import re
# (C) backslash raw-string paths -> forward slash, in the 4 dashboards (+ any chain script with same bug)
def fix_backslash_paths(fn):
    s=open(fn).read(); orig=s
    # replace backslashes INSIDE raw-string literals r"...": only those containing a backslash (=paths)
    def repl(m):
        body=m.group(1)
        return 'r"'+body.replace('\\','/')+'"' if '\\' in body else m.group(0)
    s=re.sub(r'r"([^"\n]*)"', repl, s)
    # also single-quoted raw strings r'...'
    def repl2(m):
        body=m.group(1)
        return "r'"+body.replace('\\','/')+"'" if '\\' in body else m.group(0)
    s=re.sub(r"r'([^'\n]*)'", repl2, s)
    if s!=orig: open(fn,'w').write(s); return True
    return False

